import numpy as np
import matplotlib.pyplot as plt


def plot_stacked_runtimes(runtimes1, runtimes2, runtimes3, path, label1='Light', label2='Euler', label3='Argus'):
    snapshots = list(range(len(runtimes1)))
    bar_width = 0.6
    fig_width = max(12, len(snapshots) * 0.05)

    fig, ax = plt.subplots(figsize=(fig_width, 4))

    runtimes1 = np.array(runtimes1) * 1000
    ax.bar(
        snapshots, runtimes1,
        width=bar_width,
        label=label1,
        color='#000000',
        alpha=0.8,
        edgecolor='none'
    )

    runtimes2 = np.array(runtimes2) * 1000
    ax.bar(
        snapshots, runtimes2,
        width=bar_width,
        bottom=runtimes1,
        label=label2,
        color='#008000',
        alpha=0.8,
        edgecolor='none'
    )

    if runtimes3 is not None:
        bottom_two = [a + b for a, b in zip(runtimes1, runtimes2)]

        runtimes3 = np.array(runtimes3) * 1000
        ax.bar(
            snapshots, runtimes3,
            width=bar_width,
            bottom=bottom_two,
            label=label3,
            color='#ff8000',
            alpha=0.8,
            edgecolor='none'
        )

    ax.set_xlabel('Snapshot', fontsize=18)
    ax.set_ylabel('Runtime (ms)', fontsize=18)
    ax.set_xlim([-1, len(runtimes1)])
    ax.set_ylim(1, 1000)
    ax.set_yscale('log')
    ax.legend(fontsize=15, loc='upper right')
    ax.grid(False)
    ax.tick_params(axis='both', which='major', labelsize=16)

    plt.tight_layout()
    plt.savefig(path)
    

